// Browser half of the startup-screen plugin: a full-screen HUD boot animation.
//
// The animation is the standalone page (startup/startup-anim.html) embedded as
// base64 and mounted inside a same-page iframe, so its styles and ids can never
// leak into the harness UI. It plays once per browser session: the first load
// shows it, later reloads (including HMR swaps) do not.
window.__ModuleLoader__.load({
  id: 'dsh-startup-screen',
  factory: (require) => {
    var module = { exports: {} }
    var exports = module.exports

    var HTML_B64 = ''
    var MUSIC_B64 = ''
    var SEEN_KEY = 'dsh-startup-screen:played'
    var Z = 2147483000

    function decodeUtf8(b64) {
      var bin = atob(b64)
      var bytes = new Uint8Array(bin.length)
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
      return new TextDecoder('utf-8').decode(bytes)
    }

    var state = { el: null, frame: null, audio: null, timer: 0, dispose: null }

    function teardown(fast) {
      var el = state.el
      if (!el) return
      state.el = null
      clearTimeout(state.timer)
      state.timer = 0
      if (state.audio) {
        try { state.audio.pause() } catch (e) {}
        state.audio.src = ''
        state.audio = null
      }
      if (typeof state.dispose === 'function') {
        try { state.dispose() } catch (e) {}
        state.dispose = null
      }
      var frame = state.frame
      state.frame = null
      el.style.transition = fast ? 'none' : 'opacity 420ms ease'
      el.style.opacity = '0'
      setTimeout(function () {
        if (frame && frame.parentNode) frame.parentNode.removeChild(frame)
        if (el.parentNode) el.parentNode.removeChild(el)
      }, fast ? 0 : 460)
      try { sessionStorage.setItem(SEEN_KEY, '1') } catch (e) {}
    }

    function mount(ctx) {
      if (!document.body) return
      var force = /(?:^|[?&])startup=1(?:&|$)/.test(location.search)
      if (!force) {
        try {
          if (sessionStorage.getItem(SEEN_KEY) === '1') return
        } catch (e) {}
      }

      var el = document.createElement('div')
      el.setAttribute('data-dsh-startup-screen', '')
      el.style.cssText = [
        'position:fixed', 'inset:0', 'z-index:' + Z,
        'background:#000', 'opacity:1', 'transition:opacity 420ms ease',
        'overflow:hidden', 'cursor:default',
      ].join(';')

      var frame = document.createElement('iframe')
      frame.setAttribute('allow', 'autoplay')
      frame.setAttribute('scrolling', 'no')
      frame.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;border:0;display:block'
      frame.srcdoc = decodeUtf8(HTML_B64)

      // click catcher: keeps the overlay's own gestures in the parent frame
      var catcher = document.createElement('div')
      catcher.style.cssText = 'position:absolute;inset:0;background:transparent;z-index:2'

      var hint = document.createElement('div')
      hint.textContent = '点击任意处开启声音 · ESC 跳过'
      hint.style.cssText = [
        'position:absolute', 'right:26px', 'bottom:22px', 'z-index:3',
        'font:11px/1.4 system-ui,sans-serif', 'letter-spacing:2px',
        'color:rgba(190,205,215,.5)', 'pointer-events:none',
        'opacity:0', 'transition:opacity 300ms ease',
      ].join(';')

      el.appendChild(frame)
      el.appendChild(catcher)
      el.appendChild(hint)
      document.body.appendChild(el)
      state.el = el
      state.frame = frame

      // ---- score: browsers only allow audio after a user gesture ----
      var audioBlocked = false
      function startAudio() {
        if (!state.audio || !audioBlocked) return
        audioBlocked = false
        hint.style.opacity = '0'
        var r = state.audio.play()
        if (r && typeof r.catch === 'function') r.catch(function () {})
      }
      if (MUSIC_B64) {
        try {
          var bin = atob(MUSIC_B64)
          var bytes = new Uint8Array(bin.length)
          for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
          var blobUrl = URL.createObjectURL(new Blob([bytes], { type: 'audio/mpeg' }))
          var audio = new Audio(blobUrl)
          audio.preload = 'auto'
          audio.volume = 0.9
          state.audio = audio
          var p = audio.play()
          if (p && typeof p.catch === 'function') {
            p.catch(function () {
              audioBlocked = true
              hint.style.opacity = '1'
              setTimeout(function () { hint.style.opacity = '0' }, 9000)
            })
          }
        } catch (e) {}
      }

      // ---- dismissal: ESC / Space / click, or when the animation ends ----
      var t0 = Date.now()
      function skip(event) {
        if (Date.now() - t0 < 1200) return
        if (event && event.type === 'keydown') {
          var k = event.key
          if (k !== 'Escape' && k !== ' ' && k !== 'Enter') return
        }
        if (audioBlocked) { startAudio(); return }
        if (event) { event.preventDefault(); event.stopPropagation() }
        window.removeEventListener('keydown', skip, true)
        teardown(false)
      }
      window.addEventListener('keydown', skip, true)
      catcher.addEventListener('pointerdown', skip, true)

      var duration = 38400
      try {
        var doc = frame.contentDocument
        if (doc && doc.defaultView && doc.defaultView.DURATION) {
          duration = doc.defaultView.DURATION * 1000
        }
      } catch (e) {}
      state.timer = setTimeout(function () {
        window.removeEventListener('keydown', skip, true)
        teardown(false)
      }, duration + 400)

      state.dispose = function () {
        window.removeEventListener('keydown', skip, true)
      }
    }

    function apply(ctx) {
      try {
        if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', function () { mount(ctx) }, { once: true })
        } else {
          mount(ctx)
        }
      } catch (e) {
        try { console.error('[startup-screen] mount failed:', e) } catch (e2) {}
        try { teardown(true) } catch (e3) {}
      }
      if (typeof ctx.effect === 'function') {
        ctx.effect(function () {
          return function () { teardown(true) }
        }, 'dsh-startup-screen: overlay')
      }
    }

    exports.apply = apply
    exports.inject = []

    return module.exports
  },
})
